const input = $input.first().json.body || $input.first().json;
const query = String(input.query || input.title || '').trim();
if (query.length < 3) throw new Error('Provide a search query with at least 3 characters');
const deals = Array.isArray(input.deals) ? input.deals.slice(0, 100) : [];
const demands = Array.isArray(input.demands) ? input.demands.slice(0, 100) : [];
const prompt = `You help residents find relevant group-buying deals and community demands. Match only against the supplied catalog; do not invent offers, vendors, prices, certifications, savings or availability. Keep reasons short and evidence-based. Do not ask for personal or payment details.
Resident query: ${query}
Available deals: ${JSON.stringify(deals)}
Open demands: ${JSON.stringify(demands)}
Return only JSON {"matches":[{"type":"DEAL|DEMAND","id":"...","title":"...","confidence":0,"reason":"...","pricePerUnit":number|null,"vendor":"..."}],"suggestions":["..."],"noMatchReason":"...|"}. Confidence is 0-100; include only plausible matches and use null when a price/vendor is absent.`;
return [{ json: { query, prompt } }];

const response = $input.first().json;
const source = $('Prepare Catalog Match').first().json;
let result;
try { result = JSON.parse(response.candidates?.[0]?.content?.parts?.[0]?.text || '{}'); } catch { result = null; }
if (!result || !Array.isArray(result.matches)) result = { matches: [], suggestions: ['Try a broader product name or category.'], noMatchReason: 'Catalog match could not be generated; verify current deals manually.' };
result.matches = result.matches.filter(m => typeof m.id === 'string' && typeof m.title === 'string').map(m => ({ ...m, confidence: Math.max(0, Math.min(100, Number(m.confidence) || 0)) }));
return [{ json: { status: 'success', query: source.query, matchedAt: new Date().toISOString(), ...result } }];
